DECLARE
	v_member_no NUMBER(20);
BEGIN
	v_member_no := #{memberNo};

BEGIN
	DELETE
	FROM parents
	WHERE member_no = v_member_no;
	DELETE
	FROM class_member
	WHERE member_no = v_member_no;

COMMIT;
EXCEPTION
	WHEN OTHERS THEN
		ROLLBACK;
	RAISE;
  END;
END;
